(101, '【示例】苏州工业软件产业园招商项目', '320000', '320500', 'I65', 50000000, 300000000, '重点引进工业软件、工业互联网平台和智能制造服务企业，提供研发办公载体、人才公寓和产业基金支持。', 'ACTIVE', 9, 9, DATE_SUB(NOW(), INTERVAL 80 DAY)),
(102, '【示例】宁波储能产业基地招商项目', '330000', '330200', 'C38', 80000000, 500000000, '面向储能电池、电池管理系统和新能源电站运营企业，提供标准厂房和储能示范应用场景。', 'ACTIVE', 9, 9, DATE_SUB(NOW(), INTERVAL 77 DAY)),
(103, '【示例】合肥高端装备制造招商项目', '340000', '340100', 'C34', 60000000, 400000000, '引进精密制造、工业机器人和智能成套装备企业，配套建设检验检测中心和技能人才培训基地。', 'ACTIVE', 10, 10, DATE_SUB(NOW(), INTERVAL 74 DAY)),
(104, '【示例】上海供应链总部招商项目', '310000', '310100', 'F51', 100000000, 800000000, '面向供应链管理、国际贸易和现代物流企业，提供总部办公载体和跨境贸易服务。', 'ACTIVE', 1, 1, DATE_SUB(NOW(), INTERVAL 71 DAY)),
(105, '【示例】深圳半导体封测招商项目', '440000', '440300', 'C39', 150000000, 1000000000, '重点引进集成电路封装测试、先进封测材料和设备企业，提供洁净厂房和产业配套。', 'ACTIVE', 9, 9, DATE_SUB(NOW(), INTERVAL 68 DAY)),
(106, '【示例】济南生物材料中试基地项目', '370000', '370100', 'C27', 30000000, 200000000, '面向生物医用材料、医疗器械和生物制造企业，提供中试平台、共享实验室和注册申报服务。', 'DRAFT', 10, 10, DATE_SUB(NOW(), INTERVAL 65 DAY)),
(107, '【示例】武汉绿色建筑产业园招商项目', '420000', '420100', 'N77', 40000000, 300000000, '引进绿色建材、节能环保和建筑科技企业，打造绿色建筑示范园区。', 'ACTIVE', 10, 10, DATE_SUB(NOW(), INTERVAL 62 DAY)),
(108, '【示例】成都电子信息产业招商项目', '510000', '510100', 'C39', 80000000, 600000000, '面向新型显示、智能终端和电子元器件企业，提供标准厂房和产业基金支持。', 'ACTIVE', 9, 9, DATE_SUB(NOW(), INTERVAL 59 DAY)),
(109, '【示例】厦门海洋装备招商项目', '350000', '350200', 'C37', 50000000, 350000000, '引进海洋工程装备、船舶配套和海洋电子信息企业，提供岸线资源和产业载体。', 'PAUSED', 10, 10, DATE_SUB(NOW(), INTERVAL 56 DAY)),
(110, '【示例】长沙工程机械配套招商项目', '430000', '430100', 'C34', 60000000, 450000000, '面向工程机械核心零部件、液压系统和智能控制系统企业，提供整机厂配套订单。', 'ACTIVE', 1, 1, DATE_SUB(NOW(), INTERVAL 53 DAY)),
(111, '【示例】郑州现代物流枢纽招商项目', '410000', '410100', 'G54', 50000000, 400000000, '引进冷链物流、供应链金融和多式联运企业，依托航空港和铁路枢纽建设区域物流中心。', 'ACTIVE', 9, 9, DATE_SUB(NOW(), INTERVAL 50 DAY)),
(112, '【示例】西安硬科技产业园招商项目', '610000', '610100', 'M73', 40000000, 300000000, '面向航空航天、新材料和科技研发企业，提供实验室、中试基地和人才政策。', 'DRAFT', 10, 10, DATE_SUB(NOW(), INTERVAL 47 DAY)),
(113, '【示例】青岛新能源整车配套招商项目', '370000', '370200', 'C36', 80000000, 700000000, '引进新能源汽车整车配套、三电系统和智能网联企业，提供整车厂协同机会。', 'ACTIVE', 9, 9, DATE_SUB(NOW(), INTERVAL 44 DAY)),
(114, '【示例】福州数字经济产业园招商项目', '350000', '350100', 'I64', 30000000, 250000000, '面向互联网服务、数字内容和平台经济企业，提供办公载体和算力支持。', 'ACTIVE', 10, 10, DATE_SUB(NOW(), INTERVAL 41 DAY)),
(115, '【示例】天津生物医药外包招商项目', '120000', '120100', 'C27', 50000000, 350000000, '引进医药研发外包、临床研究和医疗器械服务企业，提供研发楼和共享实验平台。', 'ACTIVE', 1, 1, DATE_SUB(NOW(), INTERVAL 38 DAY)),
(116, '【示例】重庆智能网联汽车招商项目', '500000', '500100', 'C36', 100000000, 800000000, '面向智能网联汽车、车联网和汽车软件企业，提供测试道路和整车配套资源。', 'ACTIVE', 9, 9, DATE_SUB(NOW(), INTERVAL 35 DAY)),
(117, '【示例】无锡物联网创新中心招商项目', '320000', '320200', 'C39', 40000000, 300000000, '引进物联网、传感器和工业互联网企业，提供创新中心载体和示范应用场景。', 'CLOSED', 10, 10, DATE_SUB(NOW(), INTERVAL 32 DAY));
